package com.termux.app.workspace;
import android.app.*;import android.view.*;import android.widget.*;import android.content.*;import android.content.res.Configuration;import com.termux.R;import com.termux.app.TermuxActivity;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class SidebarTreeTest {
 Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 int width(WorkspaceSidebar m)throws Exception{Method f=WorkspaceSidebar.class.getDeclaredMethod("width");f.setAccessible(true);return(int)f.invoke(m);}
 void layout(View v,int w,int h){v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);}
 List<String> labels(ViewGroup group){List<String> result=new ArrayList<>();for(int i=0;i<group.getChildCount();i++){View v=group.getChildAt(i);if(v instanceof TextView)result.add(((TextView)v).getText().toString());}return result;}
 @Test public void everyOwnerHasItsOwnLineAndNonCollapsibleGroupsWithIndependentCallbacks(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();WorkspaceSidebar menu=new WorkspaceSidebar(a);AtomicInteger actions=new AtomicInteger(-1);for(int i=0;i<5;i++){final int owner=i;actions.set(-1);LinearLayout branch=menu.session("id"+i,"Name","/path",false,false,false,()->false,()->{},()->{},()->{});assertTrue(branch instanceof SidebarTreeActions);LinearLayout group=menu.group(branch,"Project","project");menu.action(group,"Files",R.drawable.workspace_folder,()->actions.set(owner));View title=((ViewGroup)group.getParent()).findViewWithTag("sidebar-group-title");assertFalse(title.hasOnClickListeners());assertFalse(title.performClick());assertEquals(-1,actions.get());LinearLayout frame=(LinearLayout)branch.getParent();((ViewGroup)frame.getChildAt(0)).getChildAt(0).performClick();assertEquals(View.VISIBLE,branch.getVisibility());assertTrue(((LinearLayout.LayoutParams)branch.getLayoutParams()).leftMargin>0);assertTrue(group.getPaddingLeft()>0);group.getChildAt(0).performClick();assertEquals(i,actions.get());assertSame(menu.body,frame.getParent());}menu.dispose();}
 @Test public void contentScaleIsUniformAndDoesNotChangeBaseResources(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();float d=a.getResources().getDisplayMetrics().density,sd=a.getResources().getDisplayMetrics().scaledDensity;int dpi=a.getResources().getConfiguration().densityDpi;WorkspaceSidebar menu=new WorkspaceSidebar(a);TextView row=menu.action(menu.body,"Action",R.drawable.workspace_folder,()->{});menu.section("Section");LinearLayout branch=menu.session("id","Title","Path",false,false,false,()->false,()->{},()->{},()->{});assertEquals(d*.8,row.getResources().getDisplayMetrics().density,.01);assertEquals(20.5*sd*.8,row.getTextSize(),.1);assertEquals(Math.round(48*d*.8),row.getMinHeight(),1);assertEquals(Math.round(24*d*.8),row.getCompoundDrawables()[0].getBounds().width(),1);TextView section=(TextView)menu.body.getChildAt(1);assertEquals(22*sd*.8,section.getTextSize(),.1);TextView title=menu.body.findViewWithTag("sidebar-session-title"),subtitle=menu.body.findViewWithTag("sidebar-session-subtitle");assertEquals(20.5*sd*.8,title.getTextSize(),.1);assertEquals(16*sd*.8,subtitle.getTextSize(),.1);assertEquals(dpi,a.getResources().getConfiguration().densityDpi);assertEquals(1,branch.getScaleX(),0);menu.dispose();}
 @Test public void boundedWidthFitsActionMetricsAndIgnoresChatNamesAndPaths()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();WorkspaceSidebar menu=new WorkspaceSidebar(a);TextView action=menu.action(menu.body,"Open",0,()->{});int small=width(menu);action.setMinWidth(220);int large=width(menu);assertTrue(large>=small);String huge=String.join("",Collections.nCopies(200,"Очень длинный проект / "));menu.session("id",huge,huge,false,false,false,()->false,()->{},()->{},()->{});assertEquals(large,width(menu));TextView title=menu.body.findViewWithTag("sidebar-session-title"),path=menu.body.findViewWithTag("sidebar-session-subtitle");assertNotNull(title.getEllipsize());assertNotNull(path.getEllipsize());layout((View)menu.scroll.getParent(),320,640);assertTrue(menu.scroll.getLayoutParams().width<=256);assertTrue(menu.scroll.getLayoutParams().width<320);menu.dispose();}
 @Test public void controllerBuildsRequestedGroupsForAllAgentsAndProtectsBaseSettings()throws Exception{TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);a.setContentView(R.layout.activity_termux);set(a,"mTerminalView",a.findViewById(R.id.terminal_view));WorkspaceLanguage.select(a,"ru");WorkspaceController c=new WorkspaceController(a);WorkspaceStore store=(WorkspaceStore)get(c,"store");List<WorkspaceStore.Session> profiles=new ArrayList<>();for(String agent:new String[]{"codex","claude","gemini","opencode","terminal"}){WorkspaceStore.Session p=new WorkspaceStore.Session();p.name=agent;p.saved=true;p.environment=agent.equals("codex")?"codex":"ubuntu";p.claudeAgent=agent.equals("claude");p.geminiAgent=agent.equals("gemini");p.aiAgent=agent.equals("opencode")?"opencode":"";store.sessions.add(p);profiles.add(p);}WorkspaceStore.Session base=new WorkspaceStore.Session();base.id=WorkspaceStore.BASE_TERMINAL_ID;base.environment="termux";base.name="Base";store.sessions.add(base);try{Method build=WorkspaceController.class.getDeclaredMethod("createSidebar");build.setAccessible(true);WorkspaceSidebar menu=(WorkspaceSidebar)build.invoke(c);for(int i=0;i<profiles.size();i++){WorkspaceStore.Session p=profiles.get(i);ViewGroup frame=menu.body.findViewWithTag("sidebar-session-"+p.id);assertNotNull(frame);LinearLayout branch=(LinearLayout)frame.getChildAt(1);String prefix=i<4?"project":"environment";LinearLayout items=branch.findViewWithTag("sidebar-group-items-"+prefix);assertNotNull(items);if(i<4){assertEquals("Файлы и изменения проекта",labels(items).get(0));assertEquals("Навыки агента",labels(items).get(labels(items).size()-1));LinearLayout manage=branch.findViewWithTag("sidebar-group-items-chat-management");assertEquals(Arrays.asList("Лимиты и контекст","Права и подтверждения","Настройки сессии"),labels(manage));}else{assertEquals(Arrays.asList("Файлы окружения","Программы","Пакеты окружения","Документация окружения"),labels(items));assertEquals("Открыть рабочий стол",((TextView)branch.getChildAt(1)).getText().toString());assertEquals("sidebar-desktop-stop-"+p.id,branch.getChildAt(2).getTag());assertEquals(View.GONE,branch.getChildAt(2).getVisibility());}}ViewGroup baseFrame=menu.body.findViewWithTag("sidebar-session-"+base.id);LinearLayout manage=baseFrame.findViewWithTag("sidebar-group-items-session-management");assertFalse(labels(manage).contains("Настройки сессии"));assertTrue(labels(manage).contains("Настройки рабочего стола"));menu.dispose();}finally{c.close();}}
}
